mapper.select:
SELECT doc_id
FROM doc_schedule_record
WHERE id = #{scheduleRecordId}

SELECT id, overage
FROM medical_insurance
WHERE id = #{medicalInsuranceId}

mapper.update:
UPDATE medical_insurance
SET overage = overage - #{amount}
WHERE id = #{medicalInsuranceId}
  AND overage >= #{amount}

mapper.select:
SELECT medical_insuranceid
FROM patient
WHERE id = #{patientId}

SELECT id, patient_id AS "patientId", sch_id AS "schId", pay_status AS "payStatus"
FROM pay_record
WHERE id = #{paymentId}
